"""Readable output: Markdown and a self-contained HTML page."""
from __future__ import annotations

import html

ICON = {"matched": "✅", "partial": "🟡", "missing": "❌"}
LABEL = {"matched": "Matched", "partial": "Partial", "missing": "Missing"}


def to_markdown(r: dict) -> str:
    g, job, c = r["gap"], r["job"], r["candidate"]
    L = [f"# Job Preparation Report: {job['title']}", "",
         f"**Match score: {g['score']}% ({g['fit']} fit)**" if g["score"] is not None else "**No match score**",
         "", g["summary"], "", f"_Advice generated by: {'Claude' if r['mode'] == 'llm' else 'rules engine (offline)'}_", "",
         "## Skill gap", "", "| Skill | Tier | Status | Why |", "|---|---|---|---|"]
    for i in g["items"]:
        L.append(f"| {i['skill']} | {i['tier']} | {ICON[i['status']]} {LABEL[i['status']]} | {i['reason']} |")
    L += ["", f"**Experience:** {g['experience']['text']}", ""]

    p = r["plan"]
    L += ["## Learning plan", ""]
    if p["steps"]:
        if p["emphasise_on_resume"]:
            L += [f"Lead your resume with: {', '.join(p['emphasise_on_resume'])}.", ""]
        for s in p["steps"]:
            L += [f"### {s['priority']}. {s['skill']} (weeks {s['start_week']}-{s['end_week']})", "",
                  s["explanation"], "", "Study: " + "; ".join(s["topics"]), "",
                  f"Prove it with: {s['practice_project']}", ""]
        L += [f"Total: about {p['total_weeks']} weeks. {p['note']}", ""]
        if p["not_in_plan"]:
            L += [f"Not in this plan (lower priority): {', '.join(p['not_in_plan'])}.", ""]
    else:
        L += ["No skill gaps to plan for.", ""]

    L += ["## Interview questions", ""]
    for n, q in enumerate(r["questions"], 1):
        L += [f"{n}. **{q['question']}**", f"   _Why this question:_ {q['why']}", ""]

    L += ["## What was found on the resume", ""]
    full = [s for s, v in c["skills"].items() if v["level"] == "full" and v["strength"] != "implied"]
    part = [s for s, v in c["skills"].items() if v["level"] == "partial"]
    L += [f"- Skills: {', '.join(full) or 'none'}"]
    if part:
        L += [f"- Basic or learning: {', '.join(part)}"]
    if c["negated_skills"]:
        L += [f"- Stated no experience: {', '.join(c['negated_skills'])}"]
    if c["unrecognised_skills"]:
        L += [f"- Listed but not in the knowledge base (not scored): {', '.join(c['unrecognised_skills'])}"]
    L += [f"- Education: {'; '.join(e['text'] for e in c['education']) or 'not found'}",
          f"- Projects: {'; '.join(p['title'] for p in c['projects']) or 'not found'}"]
    if r["warnings"]:
        L += ["", "## Warnings", ""] + [f"- {w}" for w in r["warnings"]]
    return "\n".join(L) + "\n"


CSS = """
:root{--bg:#fbfaf7;--fg:#1f2328;--muted:#5b6370;--card:#fff;--line:#e3e0d8;--ok:#1a7f4b;--mid:#b7791f;--bad:#c2410c;--accent:#3b5bdb}
@media (prefers-color-scheme:dark){:root{--bg:#15171a;--fg:#e6e6e6;--muted:#9aa3ad;--card:#1d2024;--line:#2d3137;--ok:#4ade80;--mid:#fbbf24;--bad:#fb923c;--accent:#8ea4ff}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.55 system-ui,-apple-system,Segoe UI,sans-serif}
main{max-width:960px;margin:0 auto;padding:28px 16px 64px}h1{font-size:25px;margin:0 0 6px}h2{margin-top:36px;font-size:19px}
.score{display:flex;align-items:center;gap:20px;background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 20px;margin:16px 0;flex-wrap:wrap}
.big{font-size:44px;font-weight:700;line-height:1}.meter{flex:1;min-width:200px;height:10px;background:var(--line);border-radius:99px;overflow:hidden}
.meter i{display:block;height:100%;background:var(--accent)}.muted{color:var(--muted);font-size:13px}
.tablewrap{overflow-x:auto}table{border-collapse:collapse;width:100%;background:var(--card);border:1px solid var(--line);font-size:14px}
th,td{text-align:left;padding:8px 10px;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--muted)}
.matched{color:var(--ok);font-weight:600}.partial{color:var(--mid);font-weight:600}.missing{color:var(--bad);font-weight:600}
.card{background:var(--card);border:1px solid var(--line);border-left:4px solid var(--accent);border-radius:10px;padding:12px 16px;margin:12px 0}
.card h3{margin:0 0 4px;font-size:16px}code{font:12.5px ui-monospace,Menlo,monospace}ol li{margin:10px 0}
"""


def to_html(r: dict) -> str:
    e = html.escape
    g, job, c, p = r["gap"], r["job"], r["candidate"], r["plan"]
    rows = "".join(
        f"<tr><td><b>{e(i['skill'])}</b></td><td>{i['tier']}</td><td class='{i['status']}'>{ICON[i['status']]} {LABEL[i['status']]}</td>"
        f"<td>{e(i['reason'])}</td></tr>" for i in g["items"])
    steps = "".join(
        f"<div class='card'><h3>{s['priority']}. {e(s['skill'])} <span class='muted'>weeks {s['start_week']}-{s['end_week']}</span></h3>"
        f"<p>{e(s['explanation'])}</p><p><b>Study:</b> {e('; '.join(s['topics']))}</p>"
        f"<p><b>Prove it with:</b> {e(s['practice_project'])}</p></div>" for s in p["steps"]) or "<p>No skill gaps to plan for.</p>"
    qs = "".join(f"<li><b>{e(q['question'])}</b><br><span class='muted'>Why: {e(q['why'])}</span></li>" for q in r["questions"])
    score = g["score"] if g["score"] is not None else 0
    warn = "".join(f"<li>{e(w)}</li>" for w in r["warnings"])
    return f"""<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Job Preparation Report</title><style>{CSS}</style></head><body><main>
<h1>Job Preparation Report</h1><div class="muted">{e(job['title'])} · advice by {'Claude' if r['mode'] == 'llm' else 'rules engine (offline)'}</div>
<div class="score"><div class="big">{score}%</div><div><b>{e(str(g['fit']))} fit</b><div class="muted">{e(g['experience']['text'])}</div></div>
<div class="meter"><i style="width:{score}%"></i></div></div>
<p>{e(g['summary'])}</p>
<h2>Skill gap</h2><div class="tablewrap"><table><tr><th>Skill</th><th>Tier</th><th>Status</th><th>Why</th></tr>{rows}</table></div>
<h2>Learning plan</h2>{('<p class="muted">Lead your resume with: ' + e(', '.join(p['emphasise_on_resume'])) + '.</p>') if p['emphasise_on_resume'] else ''}{steps}
<p class="muted">{e(p['note'])}</p>
<h2>Interview questions</h2><ol>{qs}</ol>
{('<h2>Warnings</h2><ul>' + warn + '</ul>') if warn else ''}
</main></body></html>"""
